cat > /workspace/cmd/gowsdl/main.go << 'EOF'
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/local/gowsdl/pkg/gowsdl"
)

const version = "v0.5.0"

func init() {
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage: %s [options] myservice.wsdl\n", os.Args[0])
		flag.PrintDefaults()
	}
}

func main() {
	var (
		pkg        = flag.String("p", "myservice", "Package under which code will be generated")
		outFile    = flag.String("o", "myservice.go", "File where the generated code will be saved")
		dir        = flag.String("d", "./", "Directory under which package directory will be created")
		insecure   = flag.Bool("i", false, "Skips TLS Verification")
		makePublic = flag.Bool("make-public", true, "Make the generated types public/exported")
		showVer    = flag.Bool("v", false, "Shows gowsdl version")
	)
	flag.Parse()

	if *showVer {
		fmt.Printf("🍀  %s\n", version)
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(0)
	}

	wsdlPath := args[0]
	gw, err := gowsdl.NewGoWSDL(wsdlPath, *pkg, *insecure, *makePublic)
	if err != nil {
		fmt.Printf("🍀  %s\n", err)
		os.Exit(0)
	}

	code, err := gw.Start()
	if err != nil {
		fmt.Printf("🍀  %s\n", err)
		os.Exit(0)
	}

	pkgDir := filepath.Join(*dir, *pkg)
	if err := os.MkdirAll(pkgDir, 0744); err != nil {
		fmt.Printf("🍀  %s\n", err)
		os.Exit(0)
	}

	// Write main file
	mainPath := filepath.Join(pkgDir, *outFile)
	if err := writeFile(mainPath, code["main"]); err != nil {
		fmt.Printf("🍀  %s\n", err)
		os.Exit(0)
	}

	// Write server file if service exists
	if srv, ok := code["server"]; ok && len(srv) > 0 {
		srvPath := filepath.Join(pkgDir, "server"+*outFile)
		if err := writeFile(srvPath, srv); err != nil {
			fmt.Printf("🍀  %s\n", err)
			os.Exit(0)
		}
	}

	fmt.Println("🍀  Done 👍")
}

func writeFile(path string, data []byte) error {
	// Detect if the output starts with a header comment
	_ = strings.TrimSpace
	return os.WriteFile(path, data, 0664)
}
EOF

