package gowsdl

import "encoding/xml"

// WsdlDefinitions is the top-level WSDL element
type WsdlDefinitions struct {
	XMLName         xml.Name        `xml:"http://schemas.xmlsoap.org/wsdl/ definitions"`
	Name            string          `xml:"name,attr"`
	TargetNamespace string          `xml:"targetNamespace,attr"`
	Imports         []*WsdlImport   `xml:"import"`
	Documentation  string          `xml:"documentation"`
	Types           WsdlType        `xml:"types"`
	Messages        []*WsdlMessage  `xml:"message"`
	PortTypes       []*WsdlPortType `xml:"portType"`
	Bindings        []*WsdlBinding  `xml:"binding"`
	Services        []*WsdlService  `xml:"service"`
}

type WsdlImport struct {
	Namespace string `xml:"namespace,attr"`
	Location  string `xml:"location,attr"`
}

type WsdlType struct {
	Doc     string       `xml:"documentation"`
	Schemas []*XSDSchema `xml:"schema"`
}

type WsdlMessage struct {
	Name string      `xml:"name,attr"`
	Doc  string      `xml:"documentation"`
	Parts []*WsdlPart `xml:"part"`
}

type WsdlPart struct {
	Name    string `xml:"name,attr"`
	Element string `xml:"element,attr"`
	Type    string `xml:"type,attr"`
}

type WsdlPortType struct {
	Name       string           `xml:"name,attr"`
	Doc        string           `xml:"documentation"`
	Operations []*WsdlOperation `xml:"operation"`
}

type WsdlOperation struct {
	Name    string       `xml:"name,attr"`
	Doc     string       `xml:"documentation"`
	Input   WsdlMessageRef `xml:"input"`
	Output  WsdlMessageRef `xml:"output"`
	Faults  []*WsdlFault   `xml:"fault"`
	// For bindings:
	SoapOperation *SoapOperation `xml:"operation"`
	BindingInput  *WsdlBindingIO `xml:"input"`
	BindingOutput *WsdlBindingIO `xml:"output"`
}

type WsdlMessageRef struct {
	Name    string `xml:"name,attr"`
	Message string `xml:"message,attr"`
}

type WsdlFault struct {
	Name    string `xml:"name,attr"`
	Message string `xml:"message,attr"`
}

type WsdlBinding struct {
	Name        string           `xml:"name,attr"`
