var reservedWords = map[string]string{
	"break":       "break_",
	"case":        "case_",
	"chan":        "chan_",
	"const":       "const_",
	"continue":    "continue_",
	"default":     "default_",
	"defer":       "defer_",
	"else":        "else_",
	"fallthrough": "fallthrough_",
