	"select":      "select_",
	"struct":      "struct_",
	"switch":      "switch_",
	"type":        "type_",
	"var":         "var_",
}

func replaceReservedWords(s string) string {
	if r, ok := reservedWords[s]; ok {
		return r
	}
	return s
}

// removeNSPrefix strips the namespace prefix from a qualified name "ns:local" or "local".
func removeNSPrefix(s string) string {
	if i := strings.Index(s, ":"); i >= 0 {
		return s[i+1:]
	}
	return s
}

// nsPrefix returns the prefix part (or "") of "ns:local".
func nsPrefix(s string) string {
	if i := strings.Index(s, ":"); i >= 0 {
		return s[:i]
	}
	return ""
}

// makePublic capitalizes the first rune (unicode-aware).
func makePublicRune(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}

// makePrivate lowercases the first rune.
func makePrivateRune(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = unicode.ToLower(r[0])
	return string(r)
}

// reAlpha matches leading non-letter characters.
var reStartNonAlpha = regexp.MustCompile(`^[^a-zA-Z]+`)

// makePublicName ensures a Go exported name: capitalize first letter, prefix with `_` if starts with a digit.
func makePublicName(s string, makePublic bool) string {
	if s == "" {
		return s
	}
	if !makePublic {
		// Still replace reserved words
		return replaceReservedWords(s)
	}
	// If it starts with a non-letter, prefix with _
	if !unicode.IsLetter([]rune(s)[0]) {
		s = "_" + s
	}
	return makePublicRune(s)
}

func stripXsd(s string) string {
	return removeNSPrefix(s)
}
