package gowsdl

import (
	"bytes"
	"encoding/xml"
	"fmt"
	"go/format"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"text/template"
)

// GoWSDL is the main code generator.
type GoWSDL struct {
	file           string
	pkg            string
	makePublic     bool
	ignoreTLS      bool
	rawContent     []byte
	wsdl           *WsdlDefinitions
	resolvedXSD    []*XSDSchema
	loaded         map[string]bool
	currentRecTag  int
}

// NewGoWSDL constructs a GoWSDL generator by loading the WSDL file.
func NewGoWSDL(file, pkg string, ignoreTLS, makePublic bool) (*GoWSDL, error) {
	fmt.Printf("🍀  Reading file %s\n", file)
	data, err := readFile(file, ignoreTLS)
	if err != nil {
		return nil, err
	}
	return &GoWSDL{
		file:       file,
		pkg:        pkg,
		makePublic: makePublic,
		ignoreTLS:  ignoreTLS,
		rawContent: data,
		loaded:     map[string]bool{},
	}, nil
}

func readFile(path string, insecure bool) ([]byte, error) {
	u, err := url.Parse(path)
	if err == nil && (u.Scheme == "http" || u.Scheme == "https") {
		client := http.DefaultClient
		resp, err := client.Get(path)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		return io.ReadAll(resp.Body)
	}
	return os.ReadFile(path)
}

// Start parses the WSDL and generates Go source code.
func (g *GoWSDL) Start() (map[string][]byte, error) {
	// Parse WSDL
	g.wsdl = &WsdlDefinitions{}
	if err := xml.Unmarshal(g.rawContent, g.wsdl); err != nil {
		return nil, err
	}

	// Resolve imports for XSDs referenced by import/include
	for _, schema := range g.wsdl.Types.Schemas {
		if err := g.resolveSchemaImports(schema); err != nil {
			return nil, err
		}
	}

	out := map[string][]byte{}

	mainSrc, err := g.genMain()
	if err != nil {
		return nil, err
	}
	out["main"] = mainSrc

	// Only generate server if we have a service
	if g.hasService() {
		serverSrc, err := g.genServer()
		if err != nil {
			return nil, err
		}
		out["server"] = serverSrc
	}

	return out, nil
}

func (g *GoWSDL) hasService() bool {
	for _, s := range g.wsdl.Services {
		if len(s.Ports) > 0 {
			return true
		}
	}
	for _, pt := range g.wsdl.PortTypes {
		if len(pt.Operations) > 0 {
			return true
		}
	}
	return false
}

// resolveSchemaImports loads imported/included XSD files relative to the WSDL file.
func (g *GoWSDL) resolveSchemaImports(schema *XSDSchema) error {
	baseDir := filepath.Dir(g.file)
	doLoad := func(loc string) error {
		if loc == "" {
			return nil
		}
		path := loc
		u, err := url.Parse(loc)
		if err == nil && (u.Scheme == "http" || u.Scheme == "https") {
			// network load
		} else if !filepath.IsAbs(loc) {
			path = filepath.Join(baseDir, loc)
		}
		if g.loaded[path] {
			return nil
		}
		g.loaded[path] = true
		fmt.Printf("🍀  Reading file %s\n", path)
		data, err := readFile(path, g.ignoreTLS)
		if err != nil {
			return err
		}
		// Try to parse as schema
		var s XSDSchema
		if err := xml.Unmarshal(data, &s); err != nil {
			return err
		}
		g.wsdl.Types.Schemas = append(g.wsdl.Types.Schemas, &s)
		return g.resolveSchemaImports(&s)
	}
	for _, imp := range schema.Imports {
		if err := doLoad(imp.SchemaLocation); err != nil {
			return err
		}
	}
	for _, inc := range schema.Includes {
		if err := doLoad(inc.SchemaLocation); err != nil {
			return err
		}
	}
	return nil
}

// genMain produces the main (client) Go file.
func (g *GoWSDL) genMain() ([]byte, error) {
	ctx := g.buildContext()
	var buf bytes.Buffer
	tpl := template.Must(template.New("main").Funcs(g.funcMap()).Parse(mainTemplate))
	if err := tpl.Execute(&buf, ctx); err != nil {
		return nil, err
	}
	return maybeGofmt(buf.Bytes()), nil
}

// genServer produces the server Go file.
func (g *GoWSDL) genServer() ([]byte, error) {
	ctx := g.buildContext()
	var buf bytes.Buffer
	tpl := template.Must(template.New("server").Funcs(g.funcMap()).Parse(serverTemplate))
	if err := tpl.Execute(&buf, ctx); err != nil {
		return nil, err
	}
	return maybeGofmt(buf.Bytes()), nil
}

func maybeGofmt(src []byte) []byte {
	formatted, err := format.Source(src)
	if err != nil {
		// Return unformatted source on parse error
		return src
	}
	return formatted
}

// Context passed to templates.
type genContext struct {
	Pkg             string
	WSDLContent     string
	Types           []*typeCtx
	Operations      []*opCtx
	ServiceName     string
	PortTypeName    string
	WSDL            *WsdlDefinitions
	G               *GoWSDL
}

type typeCtx struct {
	Kind     string // "struct", "simple", "enum", "alias"
	Name     string
	Body     string
}

type opCtx struct {
	Name           string  // operation name, public
	OriginalName   string  // original name
	InputType      string  // Go type for request
	OutputType     string  // Go type for response
	SoapAction     string
	Doc            string
}

func (g *GoWSDL) buildContext() *genContext {
	ctx := &genContext{
		Pkg:         g.pkg,
		WSDLContent: string(g.rawContent),
		G:           g,
		WSDL:        g.wsdl,
	}

	// Collect operations from the first portType / binding
	// Build portType map
	ptMap := map[string]*WsdlPortType{}
	for _, pt := range g.wsdl.PortTypes {
		ptMap[pt.Name] = pt
	}
	bindingMap := map[string]*WsdlBinding{}
	for _, b := range g.wsdl.Bindings {
		bindingMap[b.Name] = b
	}
	msgMap := map[string]*WsdlMessage{}
	for _, m := range g.wsdl.Messages {
		msgMap[m.Name] = m
	}

	// Try to find SOAP binding, prefer one with soap:binding transport.
	var chosenPort *WsdlPortType
	var chosenBinding *WsdlBinding
	for _, svc := range g.wsdl.Services {
		for _, p := range svc.Ports {
			bname := removeNSPrefix(p.Binding)
			b, ok := bindingMap[bname]
			if !ok {
				continue
			}
			if b.SoapBinding == nil {
				continue
			}
			ptname := removeNSPrefix(b.Type)
			pt, ok := ptMap[ptname]
			if !ok {
				continue
			}
			chosenPort = pt
			chosenBinding = b
			break
		}
		if chosenPort != nil {
			break
		}
	}
	if chosenPort == nil && len(g.wsdl.PortTypes) > 0 {
		chosenPort = g.wsdl.PortTypes[0]
		for _, b := range g.wsdl.Bindings {
			if removeNSPrefix(b.Type) == chosenPort.Name {
				chosenBinding = b
				break
			}
		}
	}

	if chosenPort != nil {
		ctx.PortTypeName = chosenPort.Name
		// Gather operations
		bindingOps := map[string]*WsdlOperation{}
		if chosenBinding != nil {
			for _, op := range chosenBinding.Operations {
				bindingOps[op.Name] = op
			}
		}
		for _, op := range chosenPort.Operations {
			opc := &opCtx{
				Name:         makePublicName(op.Name, g.makePublic),
				OriginalName: op.Name,
				Doc:          strings.TrimSpace(op.Doc),
			}
			// Determine input/output types
			if op.Input.Message != "" {
				opc.InputType = g.messageGoType(msgMap, op.Input.Message)
			}
			if op.Output.Message != "" {
				opc.OutputType = g.messageGoType(msgMap, op.Output.Message)
			}
			// SOAP action
			bop := bindingOps[op.Name]
			if bop != nil && bop.SoapOperation != nil {
				opc.SoapAction = bop.SoapOperation.SoapAction
			} else {
				opc.SoapAction = "''"
			}
			if opc.SoapAction == "" {
				opc.SoapAction = "''"
			}
			ctx.Operations = append(ctx.Operations, opc)
		}
	}
	// Service name (for interfaces)
	if chosenPort != nil {
		ctx.ServiceName = chosenPort.Name
	}

	// Build the "types" section as raw generated text.
	ctx.Types = g.buildTypes()
	return ctx
}

// messageGoType resolves a message (ns:Name) to the Go type from its parts.
func (g *GoWSDL) messageGoType(msgMap map[string]*WsdlMessage, msgRef string) string {
	name := removeNSPrefix(msgRef)
	msg, ok := msgMap[name]
	if !ok {
		return ""
	}
	if len(msg.Parts) == 0 {
		return ""
	}
	p := msg.Parts[0]
	if p.Element != "" {
		return makePublicName(removeNSPrefix(p.Element), g.makePublic)
	}
	if p.Type != "" {
		return g.typeToGo(p.Type)
	}
	return ""
}

// typeToGo converts a qualified XSD type reference to a Go type string.
func (g *GoWSDL) typeToGo(t string) string {
	local := removeNSPrefix(t)
	if builtin, ok := xsd2goTypes[local]; ok {
		return builtin
	}
	return makePublicName(local, g.makePublic)
}

func (g *GoWSDL) funcMap() template.FuncMap {
	return template.FuncMap{
		"makePublic":     func(s string) string { return makePublicName(s, g.makePublic) },
		"makePrivate":    func(s string) string { return makePrivateRune(makePublicName(s, g.makePublic)) },
		"lower":          strings.ToLower,
	}
}
EOF

