				Name:         makePublicName(op.Name, g.makePublic),
				OriginalName: op.Name,
				Doc:          strings.TrimSpace(op.Doc),
			}
			// Determine input/output types
			if op.Input.Message != "" {
				opc.InputType = g.messageGoType(msgMap, op.Input.Message)
			}
			if op.Output.Message != "" {
				opc.OutputType = g.messageGoType(msgMap, op.Output.Message)
			}
			// SOAP action
			bop := bindingOps[op.Name]
			if bop != nil && bop.SoapOperation != nil {
				opc.SoapAction = bop.SoapOperation.SoapAction
			} else {
				opc.SoapAction = "''"
			}
			if opc.SoapAction == "" {
				opc.SoapAction = "''"
			}
			ctx.Operations = append(ctx.Operations, opc)
		}
	}
	// Service name (for interfaces)
	if chosenPort != nil {
		ctx.ServiceName = chosenPort.Name
	}

	// Build the "types" section as raw generated text.
	ctx.Types = g.buildTypes()
	return ctx
}

// messageGoType resolves a message (ns:Name) to the Go type from its parts.
func (g *GoWSDL) messageGoType(msgMap map[string]*WsdlMessage, msgRef string) string {
	name := removeNSPrefix(msgRef)
	msg, ok := msgMap[name]
	if !ok {
		return ""
	}
	if len(msg.Parts) == 0 {
		return ""
	}
	p := msg.Parts[0]
	if p.Element != "" {
		return makePublicName(removeNSPrefix(p.Element), g.makePublic)
	}
	if p.Type != "" {
		return g.typeToGo(p.Type)
	}
	return ""
}

// typeToGo converts a qualified XSD type reference to a Go type string.
func (g *GoWSDL) typeToGo(t string) string {
	local := removeNSPrefix(t)
	if builtin, ok := xsd2goTypes[local]; ok {
		return builtin
	}
	return makePublicName(local, g.makePublic)
}

func (g *GoWSDL) funcMap() template.FuncMap {
	return template.FuncMap{
		"makePublic":     func(s string) string { return makePublicName(s, g.makePublic) },
		"makePrivate":    func(s string) string { return makePrivateRune(makePublicName(s, g.makePublic)) },
		"lower":          strings.ToLower,
	}
}
