					sb.WriteString(formatDoc(d))
				} else {
					sb.WriteString("\n")
				}
				valName := makePublicName(e.Value, g.makePublic)
				fmt.Fprintf(&sb, "\t%s%s %s = \"%s\"\n", pub, valName, pub, e.Value)
			}
			fmt.Fprintf(&sb, ")\n")
			return []*typeCtx{{Kind: "enum", Name: pub, Body: sb.String()}}
		}
		// Plain alias
		var sb strings.Builder
		if doc := st.Doc.GetDoc(); doc != "" {
