}

// genComplexType emits a struct for a complexType.
func (g *GoWSDL) genComplexType(ct *XSDComplexType, ownerName, ns string) *typeCtx {
	name := ct.Name
	if name == "" {
		name = ownerName
	}
	if name == "" {
		return nil
	}
	pub := makePublicName(name, g.makePublic)
	var body strings.Builder
	if d := ct.Doc.GetDoc(); d != "" {
		body.WriteString(formatDoc(d))
	}
	fmt.Fprintf(&body, "type %s struct {\n", pub)
