	if ct.Choice != nil {
		for _, el := range ct.Choice.Elements {
			g.emitElement(sb, el, ns)
		}
	}
	if ct.All != nil {
		for _, el := range ct.All.Elements {
			g.emitElement(sb, el, ns)
		}
