			fmt.Fprintf(&sb, ")\n")
			return []*typeCtx{{Kind: "enum", Name: pub, Body: sb.String()}}
		}
		var sb strings.Builder
		if doc := st.Doc.GetDoc(); doc != "" {
			sb.WriteString(formatDoc(doc))
		}
		fmt.Fprintf(&sb, "type %s %s\n", pub, base)
		return []*typeCtx{{Kind: "alias", Name: pub, Body: sb.String()}}
	}
	if st.List != nil {
		item := st.List.ItemType
		goItem := g.typeToGo(item)
		var sb strings.Builder
		fmt.Fprintf(&sb, "type %s []%s\n", pub, goItem)
		return []*typeCtx{{Kind: "alias", Name: pub, Body: sb.String()}}
	}
	if st.Union != nil {
		var sb strings.Builder
		fmt.Fprintf(&sb, "type %s string\n", pub)
		return []*typeCtx{{Kind: "alias", Name: pub, Body: sb.String()}}
	}
	return nil
}

func formatDoc(doc string) string {
	doc = strings.TrimLeft(doc, " \t\n\r")
	if doc == "" {
		return ""
	}
	var sb strings.Builder
	for _, line := range strings.Split(doc, "\n") {
		line = strings.Trim(line, " \t\r")
		if line == "" {
			sb.WriteString("//\n")
			continue
		}
		sb.WriteString("// ")
		sb.WriteString(line)
		sb.WriteString("\n")
	}
	return sb.String()
}

func indentLines(text, indent string) string {
	if text == "" {
		return ""
	}
	lines := strings.Split(text, "\n")
	var sb strings.Builder
	for i, line := range lines {
		if i == len(lines)-1 && line == "" {
			continue
		}
		sb.WriteString(indent)
		sb.WriteString(line)
		sb.WriteString("\n")
	}
	return sb.String()
}

func enumValueName(value string) string {
	if value == "" {
		return "EmptyString"
	}
	var sb strings.Builder
	capitalize := true
	for _, r := range value {
		switch {
		case (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_':
			if capitalize {
				if r >= 'a' && r <= 'z' {
					r = r - 'a' + 'A'
				}
				capitalize = false
			}
			sb.WriteRune(r)
		case r == '-':
			sb.WriteRune('_')
			capitalize = true
		case r == ' ':
			capitalize = true
		default:
			capitalize = true
		}
	}
	return sb.String()
}

// genComplexType emits a struct for a named complexType. If an element in the
// document references this complexType via type=, the XMLName uses that element's name.
func (g *GoWSDL) genComplexType(ct *XSDComplexType, ownerName, ns string, elByType map[string][]*XSDElement) *typeCtx {
	name := ct.Name
	if name == "" {
		name = ownerName
	}
	if name == "" {
		return nil
	}
	pub := makePublicName(name, g.makePublic)
	var body strings.Builder
	if d := ct.Doc.GetDoc(); d != "" {
		body.WriteString(formatDoc(d))
	}
	fmt.Fprintf(&body, "type %s struct {\n", pub)
	// If the type is referenced by one or more elements of the same schema,
	// use the last one's name as the XMLName.
	if elByType != nil {
		if els, ok := elByType[name]; ok && len(els) > 0 {
			// Use the last referencing element's name.
			elName := els[len(els)-1].Name
			if elName != "" {
				fmt.Fprintf(&body, "\tXMLName xml.Name `xml:\"%s %s\"`\n", ns, elName)
			}
		}
	}
	g.emitComplexMembers(&body, ct, "", ns, "")
	fmt.Fprintf(&body, "}\n")
	return &typeCtx{Kind: "struct", Name: pub, Body: body.String()}
}

func (g *GoWSDL) genTopElement(el *XSDElement, ns string) []*typeCtx {
	if el.Name == "" {
		return nil
	}
	pub := makePublicName(el.Name, g.makePublic)
	if el.ComplexType != nil {
		var body strings.Builder
		// Top-level element with complexType: no element annotation comment.
		fmt.Fprintf(&body, "type %s struct {\n", pub)
		fmt.Fprintf(&body, "\tXMLName xml.Name `xml:\"%s %s\"`\n", ns, el.Name)
		g.emitComplexMembers(&body, el.ComplexType, "", ns, el.Name)
		fmt.Fprintf(&body, "}\n")
		return []*typeCtx{{Kind: "struct", Name: pub, Body: body.String()}}
	}
	if el.SimpleType != nil {
		return g.genSimpleType(el.SimpleType, el.Name)
	}
	if el.Type != "" {
		local := removeNSPrefix(el.Type)
		goType, isBuiltin := xsd2goTypes[local]
		if isBuiltin && strings.HasPrefix(goType, "soap.XSD") {
			var body strings.Builder
			fmt.Fprintf(&body, "type %s %s\n", pub, goType)
			fmt.Fprintf(&body, "\nfunc (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n", pub)
			fmt.Fprintf(&body, "\treturn %s(xdt).MarshalXML(e, start)\n", goType)
			fmt.Fprintf(&body, "}\n\n")
			fmt.Fprintf(&body, "func (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n", pub)
			fmt.Fprintf(&body, "\treturn (*%s)(xdt).UnmarshalXML(d, start)\n", goType)
			fmt.Fprintf(&body, "}\n")
			return []*typeCtx{{Kind: "alias", Name: pub, Body: body.String()}}
		}
		if isBuiltin {
			var body strings.Builder
			fmt.Fprintf(&body, "type %s %s\n", pub, goType)
			return []*typeCtx{{Kind: "alias", Name: pub, Body: body.String()}}
		}
		var body strings.Builder
		fmt.Fprintf(&body, "type %s %s\n", pub, makePublicName(local, g.makePublic))
		return []*typeCtx{{Kind: "alias", Name: pub, Body: body.String()}}
	}
	return nil
}

// emitComplexMembers writes struct members from a complexType.
func (g *GoWSDL) emitComplexMembers(sb *strings.Builder, ct *XSDComplexType, parentName, ns, enclosingName string) {
	if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
		ext := ct.SimpleContent.Extension
		baseLocal := removeNSPrefix(ext.Base)
		goType := ""
		if b, ok := xsd2goTypes[baseLocal]; ok {
			goType = b
		} else {
			goType = makePublicName(baseLocal, g.makePublic)
		}
		fmt.Fprintf(sb, "\n\tValue %s `xml:\",chardata\" json:\"-,\"`\n", goType)
		for _, attr := range ext.Attributes {
			g.emitAttribute(sb, attr, ns)
		}
		return
	}
	if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
		ext := ct.ComplexContent.Extension
		baseLocal := removeNSPrefix(ext.Base)
		if _, ok := xsd2goTypes[baseLocal]; !ok {
			fmt.Fprintf(sb, "\n\t*%s\n", makePublicName(baseLocal, g.makePublic))
		}
		g.emitSequence(sb, ext.Sequence, ns)
		if ext.Choice != nil {
			for _, el := range ext.Choice.Elements {
				g.emitElement(sb, el, ns)
			}
		}
		if ext.All != nil {
			for _, el := range ext.All.Elements {
				g.emitElement(sb, el, ns)
			}
		}
		for _, attr := range ext.Attributes {
			g.emitAttribute(sb, attr, ns)
		}
		return
	}
	g.emitSequence(sb, ct.Sequence, ns)
	if ct.Choice != nil {
		for _, el := range ct.Choice.Elements {
			g.emitElement(sb, el, ns)
		}
	}
	if ct.All != nil {
		for _, el := range ct.All.Elements {
			g.emitElement(sb, el, ns)
		}
	}
	for _, attr := range ct.Attributes {
		g.emitAttribute(sb, attr, ns)
	}
}

func (g *GoWSDL) emitSequence(sb *strings.Builder, seq *XSDSequence, ns string) {
	if seq == nil {
		return
	}
	for _, el := range seq.Elements {
		g.emitElement(sb, el, ns)
	}
	for _, ch := range seq.Choices {
		for _, el := range ch.Elements {
			g.emitElement(sb, el, ns)
		}
	}
}

func (g *GoWSDL) emitElement(sb *strings.Builder, el *XSDElement, ns string) {
	name := el.Name
	if name == "" && el.Ref != "" {
		name = removeNSPrefix(el.Ref)
	}
	if name == "" {
		return
	}
	pub := makePublicName(name, g.makePublic)
	goType := ""
	isPtr := false
	hasInnerSimpleType := false
	hasInnerComplexType := false
	suppressDoc := false
	if el.Type != "" {
		local := removeNSPrefix(el.Type)
		if b, ok := xsd2goTypes[local]; ok {
			goType = b
		} else {
			goType = makePublicName(local, g.makePublic)
			isPtr = true
		}
	} else if el.ComplexType != nil {
		hasInnerComplexType = true
		suppressDoc = true
		var inner strings.Builder
		fmt.Fprintf(&inner, "struct {\n")
		g.emitComplexMembers(&inner, el.ComplexType, "", ns, name)
		fmt.Fprintf(&inner, "}")
		goType = inner.String()
	} else if el.SimpleType != nil {
		hasInnerSimpleType = true
		if el.SimpleType.Restriction != nil {
			base := el.SimpleType.Restriction.Base
			local := removeNSPrefix(base)
			if b, ok := xsd2goTypes[local]; ok {
				goType = b
			} else {
				goType = makePublicName(local, g.makePublic)
			}
		} else {
			goType = "string"
		}
	} else {
		goType = "string"
	}
	_ = hasInnerComplexType
	isArray := el.MaxOccurs == "unbounded" || (el.MaxOccurs != "" && el.MaxOccurs != "1" && el.MaxOccurs != "0")
	if isArray {
		if isPtr {
			goType = "[]*" + goType
		} else {
			goType = "[]" + goType
		}
	} else if isPtr {
		goType = "*" + goType
	}

	sb.WriteString("\n")
	doc := el.Doc.GetDoc()
	if doc != "" && !suppressDoc {
		sb.WriteString(formatDoc(doc))
		if hasInnerSimpleType {
			sb.WriteString("\n")
		}
	}
	fmt.Fprintf(sb, "\t%s %s `xml:\"%s,omitempty\" json:\"%s,omitempty\"`\n", pub, goType, name, name)
}

func (g *GoWSDL) emitAttribute(sb *strings.Builder, attr *XSDAttribute, ns string) {
	name := attr.Name
	if name == "" && attr.Ref != "" {
		name = removeNSPrefix(attr.Ref)
	}
	if name == "" {
		return
	}
	pub := makePublicName(name, g.makePublic)
	goType := "string"
	if attr.Type != "" {
		local := removeNSPrefix(attr.Type)
		if b, ok := xsd2goTypes[local]; ok {
			goType = b
		} else {
			goType = makePublicName(local, g.makePublic)
		}
	} else if attr.SimpleType != nil && attr.SimpleType.Restriction != nil {
		local := removeNSPrefix(attr.SimpleType.Restriction.Base)
		if b, ok := xsd2goTypes[local]; ok {
			goType = b
		} else {
			goType = makePublicName(local, g.makePublic)
		}
	}
	sb.WriteString("\n")
	if d := attr.Doc.GetDoc(); d != "" {
		sb.WriteString(formatDoc(d))
		sb.WriteString("\n")
	}
	fmt.Fprintf(sb, "\t%s %s `xml:\"%s %s,attr,omitempty\" json:\"%s,omitempty\"`\n", pub, goType, ns, name, name)
}
